    "instagram": "",
    "description": "Професійний електрик — якісно, швидко, надійно!\n\nВиконую роботи будь-якої складності для квартири, будинку чи офісу:\n• монтаж і налаштування електричних замків;\n• встановлення та підключення домофонів;\n• монтаж, заміна та ремонт електропроводки;\n• встановлення й модернізація електрощитів;\n• діагностика та ремонт електромереж;\n• заміна старих запобіжників на сучасні автоматичні вимикачі;\n• усунення коротких замикань та інших несправностей;\n• підключення освітлення, розеток, вимикачів та іншого електрообладнання.\n\nЯкісне виконання робіт, оперативний виїзд, доступні ціни та індивідуальний підхід.\n\nПрацюю в Катовіце та околицях: Chorzów, Sosnowiec, Mysłowice, Siemianowice Śląskie, Tychy, Zabrze, Gliwice та інші міста регіону.\n\nТелефон / Viber: +48539423524. Telegram: +48668567920.",
